// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address sender, uint256 amount) public {
        amount = bound(amount, 0, 1 ether);
        vm.assume(sender != address(0));

        vm.deal(sender, amount);
        vm.prank(sender);
        c.addToBalance{value: amount}();

        uint256 reported = c.getBalance(sender);
        assertTrue(reported == amount);
    }
}
